import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Root object
  const root = new Group();

  // Plane geometry – use image aspect ratio (512:320 ≈ 1.6)
  const geometry = new PlaneGeometry(1.6, 1);
  const material = new MeshBasicNodeMaterial({ map: null, transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply cinematic primitives from config
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(mesh, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // Event handlers container
  root.userData.handlers = {};

  // Hover rise‑in effect
  let hoverTimeline = null;
  root.userData.handlers.hover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(mesh.position, {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // Click emit event
  root.userData.handlers.click = () => {
    ctx.emit('hub-journal.select', {});
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    primitiveInstances.forEach((inst) => {
      if (inst.cleanup) inst.cleanup();
    });
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return root;
}
